package mx.jorge.despierta;
import android.app.*;import android.content.*;import android.location.*;import android.media.*;import android.os.*;import org.json.*;import java.util.*;
public final class JourneyEngine {
 static final Map<String,Integer> gates=new HashMap<>();static MediaPlayer earlyPlayer;
 public static void begin(TripService s){gates.clear();AudioSafety.start(s);TripHistory.add(s,"Servicio iniciado");}
 public static void end(TripService s){AudioSafety.stop(s);if(earlyPlayer!=null){earlyPlayer.release();earlyPlayer=null;}s.getSystemService(NotificationManager.class).cancel(109);TripHistory.add(s,"Vigilancia detenida / en pausa");}
 public static void decision(Context c,String id,boolean now){gates.put(id,now?JourneyRules.ARMED:JourneyRules.WAITING);c.getSystemService(NotificationManager.class).cancel(109);TripHistory.add(c,now?"Elegido avisar dentro del radio":"Elegido esperar a salir y volver a entrar");}
 public static void onLocation(TripService s,Location l){if(TripService.ringing||s.testing)return;long age=(SystemClock.elapsedRealtimeNanos()-l.getElapsedRealtimeNanos())/1000000;if(age<0||age>20000||!l.hasAccuracy()||l.getAccuracy()>150)return;TripService.lastLocationAt=System.currentTimeMillis();s.getSharedPreferences("schedule",0).edit().putLong("gpsAt",TripService.lastLocationAt).apply();Calendar now=Calendar.getInstance();float nearest=Float.MAX_VALUE;String title="";if(s.alarms==null)return;
 for(int i=0;i<s.alarms.length();i++){JSONObject a=s.alarms.optJSONObject(i);if(!s.ready(a,now))continue;int radius=a.optInt("radius",1000);if(l.getAccuracy()>radius/2f)continue;s.lastFix=SystemClock.elapsedRealtime();float[] d=new float[1];Location.distanceBetween(l.getLatitude(),l.getLongitude(),a.optDouble("lat"),a.optDouble("lon"),d);String id=a.optString("id"),name=a.optString("name","Mi parada");int state=gates.containsKey(id)?gates.get(id):JourneyRules.UNKNOWN;
 if(state==JourneyRules.UNKNOWN){state=JourneyRules.first(d[0],radius,a.optString("insideMode","ask"));gates.put(id,state);if(state==JourneyRules.ASK)ask(s,a);else if(state==JourneyRules.WAITING)TripHistory.add(s,name+": esperando a salir del radio");}
 if((state==JourneyRules.WAITING||state==JourneyRules.ASK)&&JourneyRules.left(d[0],radius,l.getAccuracy())){state=JourneyRules.ARMED;gates.put(id,state);s.getSystemService(NotificationManager.class).cancel(109);TripHistory.add(s,name+": armado después de salir");}
 if(state!=JourneyRules.ARMED){s.update(name+": ya estás dentro · toca el aviso para elegir, o sal del radio");continue;}
 String key=AlarmStore.windowKey(a,now);if(a.optBoolean("earlyEnabled")&&JourneyRules.early(d[0],radius,a.optInt("earlyRadius",radius+500),key.equals(a.optString("lastEarly")))){try{a.put("lastEarly",key);AlarmStore.put(s,a);}catch(Exception ignored){}prealert(s,a);}
 if(JourneyRules.arrive(d[0],radius,state)){try{a.put("lastFired",key);AlarmStore.put(s,a);}catch(Exception ignored){}s.name=name;TripHistory.add(s,"Llegada: "+name);s.alarm(a,"¡Tu parada está cerca! Ya puedes despertar",false);return;}if(d[0]<nearest){nearest=d[0];title=name;}}
 if(nearest<Float.MAX_VALUE)s.update(title+" · a "+Math.round(nearest)+" m");}
 static void ask(Context c,JSONObject a){NotificationManager n=c.getSystemService(NotificationManager.class);NotificationChannel channel=new NotificationChannel("journey","Estado del viaje",NotificationManager.IMPORTANCE_DEFAULT);channel.setSound(null,null);n.createNotificationChannel(channel);PendingIntent p=PendingIntent.getActivity(c,109,new Intent(c,JourneyHubActivity.class).putExtra("gateId",a.optString("id")),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);n.notify(109,new Notification.Builder(c,"journey").setSmallIcon(android.R.drawable.ic_dialog_map).setContentTitle("Ya estás dentro del radio").setContentText(a.optString("name")+" · toca para avisar ahora o esperar a salir").setContentIntent(p).setAutoCancel(true).build());TripHistory.add(c,a.optString("name")+": se pidió confirmar activación dentro del radio");}
 static void prealert(TripService s,JSONObject a){if(earlyPlayer!=null){earlyPlayer.release();earlyPlayer=null;}if(s.alertVibration&&TripService.ringing)return;PatternPlayer.play(s,VibrationPattern.PRESETS[Math.max(0,Math.min(3,a.optInt("earlyPattern",1)))],false);TripHistory.add(s,"Aviso anticipado: "+a.optString("name"));NotificationManager n=s.getSystemService(NotificationManager.class);NotificationChannel ch=new NotificationChannel("journey","Estado del viaje",NotificationManager.IMPORTANCE_DEFAULT);ch.setSound(null,null);n.createNotificationChannel(ch);PendingIntent p=PendingIntent.getActivity(s,110,new Intent(s,JourneyHubActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);n.notify(110,new Notification.Builder(s,"journey").setSmallIcon(android.R.drawable.ic_dialog_map).setContentTitle("Prepárate para bajar").setContentText(a.optString("name")+" · aviso anticipado").setContentIntent(p).setAutoCancel(true).build());
 if(a.optBoolean("earlySound")&&(!AudioSafety.strict(s)||AudioSafety.headset(s)!=null))try{MediaPlayer m=new MediaPlayer();earlyPlayer=m;m.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioOutputSettings.usage(s)).setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION).build());m.setDataSource(s,android.media.RingtoneManager.getDefaultUri(android.media.RingtoneManager.TYPE_ALARM));AudioSafety.configure(s,m);m.setOnPreparedListener(mp->{if(!TripService.ringing)mp.start();});m.setOnCompletionListener(mp->{if(earlyPlayer==mp){mp.release();earlyPlayer=null;}});m.setOnErrorListener((mp,w,e)->{if(earlyPlayer==mp){mp.release();earlyPlayer=null;}return true;});m.prepareAsync();new Handler(Looper.getMainLooper()).postDelayed(()->{if(earlyPlayer==m){m.release();earlyPlayer=null;}},2500);}catch(Exception ignored){} }
 public static void alert(Context c,boolean warning){if(earlyPlayer!=null){earlyPlayer.release();earlyPlayer=null;}if(warning){PatternPlayer.active=new long[]{0,150,150,150,150,150,1800};TripHistory.add(c,"Aviso de señal: ubicación no fiable o GPS desactivado");}}
 public static void dismissed(Context c,Intent intent){if(intent==null||!"DISMISS".equals(intent.getAction()))return;JSONArray old=AlarmStore.load(c),out=new JSONArray();for(int i=0;i<old.length();i++){JSONObject a=old.optJSONObject(i);if(a.optBoolean("oneTrip")&&a.has("lastFired")){TripHistory.add(c,"Viaje terminado: "+a.optString("name"));}else out.put(a);}AlarmStore.save(c,out);c.getSystemService(NotificationManager.class).cancel(110);TripHistory.add(c,"Aviso descartado por el usuario");}
}
